TLM.f("Sancti/10-07cc",{"officium":"Ss. Sergii, Bacchi, Marcelli et Apuleji Martyrum","rule":["vide C3a;","Suffragium=Maria3;;"],"fallback":"Commune/C3a","from":{"Introitus":"Commune/C3a","Lectio":"Commune/C3a","Graduale":"Commune/C3a","Tractus":"Commune/C3a","Evangelium":"Commune/C3a","Offertorium":"Commune/C3a","Communio":"Commune/C3a"},"sections":{"Introitus":[{"k":"ref","la":"Eccli 44:15; 44:14"},{"k":"text","la":"Sapiéntiam Sanctórum narrent populi, et laudes eórum núntiet ecclésia: nómina autem eórum vivent in sǽculum sǽculi."},{"k":"ref","la":"Ps 32:1"},{"k":"text","la":"Exsultáte, justi, in Dómino: rectos decet collaudátio."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Sapiéntiam Sanctórum narrent populi, et laudes eórum núntiet ecclésia: nómina autem eórum vivent in sǽculum sǽculi."}],"Oratio":[{"k":"text","la":"Sanctórum Martyrum tuórum nos, Dómine, Sérgii, Bacchi, Marcélli et Apuléji beáta mérita prosequántur: et tuo semper fáciant amóre fervéntes."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Lectio libri Sapientiæ"},{"k":"ref","la":"Sap 5:16-20"},{"k":"text","la":"Justi autem in perpétuum vivent, et apud Dóminum est merces eórum, et cogitátio illórum apud Altíssimum. Ideo accípient regnum decóris, et diadéma speciéi de manu Dómini: quóniam déxtera sua teget eos, et bráchio sancto suo deféndet illos. Accípiet armatúram zelus illíus, et armábit creatúram ad ultiónem inimicórum. Induet pro thoráce justítiam, et accípiet pro gálea judícium certum. Sumet scutum inexpugnábile æquitátem."}],"Graduale":[{"k":"ref","la":"Ps 123:7-8"},{"k":"text","la":"Anima nostra, sicut passer, erépta est de láqueo venántium."},{"k":"text","la":"Láqueus contrítus est, et nos liberáti sumus: adjutórium nostrum in nómine Dómini, qui fecit cœlum et terram. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 67:4"},{"k":"text","la":"Justi epuléntur, et exsúltent in conspéctu Dei: et delecténtur in lætítia. Alleluja."}],"Tractus":[{"k":"ref","la":"Ps 123:7-8"},{"k":"text","la":"Anima nostra, sicut passer, erépta est de láqueo venántium."},{"k":"text","la":"Láqueus contrítus est, et nos liberáti sumus: adjutórium nostrum in nómine Dómini, qui fecit cœlum et terram.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flebant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 6:17-23"},{"k":"text","la":"In illo témpore: Descéndens Jesus de monte, stetit in loco campéstri, et turba discipulórum ejus, et multitúdo copiósa plebis ab omni Judǽa, et Jerúsalem, et marítima, et Tyri, et Sidónis, qui venérant, ut audírent eum et sanaréntur a languóribus suis. Et, qui vexabántur a spirítibus immúndis, curabántur. Et omnis turba quærébat eum tángere: quia virtus de illo exíbat, et sanábat omnes. Et ipse, elevátis oculis in discípulos suos, dicébat: Beáti, páuperes: quia vestrum est regnum Dei. Beáti, qui nunc esurítis: quia saturabímini. Beáti, qui nunc fletis: quia ridébitis. Beáti éritis, cum vos óderint hómines, et cum separáverint vos et exprobréverint, et ejécerint nomen vestrum tamquam malum, propter Fílium hóminis. Gaudéte in illa die et exsultáte: ecce enim, merces vestra multa est in cœlo."}],"Offertorium":[{"k":"ref","la":"Ps 149:5-6"},{"k":"text","la":"Exsultábunt Sancti in glória, lætabúntur in cubílibus suis: exaltatiónes Dei in fáucibus eórum, allelúja."}],"Secreta":[{"k":"text","la":"Majestátem tuam nobis, Dómine, quǽsumus, hæc hóstia reddat immolánda placátam, tuórum digna postulatióne Sanctórum."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 12:4"},{"k":"text","la":"Dico autem vobis amícis meis: Ne terreámini ab his, qui vos persequúntur."}],"Postcommunio":[{"k":"text","la":"Sacraméntis, Dómine, muniámur accéptis: et sanctórum Mártyrum tuórum Sérgii, Bacchi, Marcélli et Apuléji intercessióne, contra omnes nequítias irruéntes, annis cœléstibus protegámur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"0a1efb6d0f799100":{"t":"<i>Pomolimo se</i>.\nNeka nas, Gospodine, prate blažene zasluge svetih tvojih mučenika Sergija, Bakha, Marcela i Apuleja i uvijek podržavaju u nama žar tvoje ljubavi.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"8a14e8f90e2080b2":{"t":"Molimo, Gospodine, da ovaj dar za prikazivanje ublaži tvoje veličanstvo po dostojnoj molbi tvojih svetih.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"a0fd8fa2439213a1":{"t":"<i>Pomolimo se</i>.\nNeka nas štite, Gospodine, primljena otajstva i po zagovoru svetih mučenika tvojih Sergija, Bakha, Marcela i Apuleja, neka nas brane nebeskim oružjem protiv svih zlih navala.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
